Definition sc_W3 (lo spa S regb : Z) : list (Z * Z) := [(lo, spa + 80); (S, S + 272); (regb + 8, regb + 48)]%Z.

(* [comment removed for export] *)
Definition sc_obj1 (ioc : Z) (j224 : list byte) : list cell :=
  [C8 (wz AVP_SCHED); CB 16 (poison_bytes 16 0); C8 (wz ioc); CB 16 (poison_bytes 16 0); CB 224 j224].

Definition scU1_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (LB : list block) (LF : list fframe)
    (S ioc regb cfgb lo shi spa ff fp : Z) (xs2 xs3 xs9 errv : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m' p16 p24 j224,
    ms' = MS (mkR (Z_to_bv 64 0xab938) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (wz cfgb) (wz AL_STR_SCHEDULER) (wz (akey_lit KChint)) (wz 0) (wz 0) a5 a6 a7
                  xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) (Z_to_bv 64 AL_TYPEID_CONFIG) (Z_to_bv 64 (S + 48))
                  (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_CONFIG_GET_INT) fc None m' (seg_rom asegs)
    /\ munch (sc_W3 lo spa S regb) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo spa
    /\ rw_cells asegs m' spa (sc_loc p16 p24 ff)
    /\ rw_cells asegs m' S (sc_obj1 ioc j224)
    /\ addressable m' S NEWSZ_SCH
    /\ asc_inv LB m' ioc regb cfgb errv
    /\ as_RFS H ((3, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.
