Lemma sc_U1 : forall (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word) (errv : word)
    (p56 p16 junk : list byte) (m : mem)
    (rax gp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 xs2 xs5 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  rw_cells asegs m spa [CB 56 p56; C8 (Z_to_bv 64 ff); CB 16 p16] ->
  rw_cells asegs m S [CB 272 junk] -> addressable m S NEWSZ_SCH -> shvis m S (S + NEWSZ_SCH) ->
  stk asegs m lo spa -> mem_inv asegs m ->
  asc_inv LB m ioc regb cfgb errv ->
  as_RFS H ((3, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi ->
  sc_side H LB LF S ioc regb cfgb lo shi spa ff fp sp tp ->
  evt asegs (scU1_post sp gp tp F fc LB LF S ioc regb cfgb lo shi spa ff fp xs2 (wz P_A_SCHED_GET_DEFAULT_TASK) xs9 errv m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) a0 a1 a2 a3 a4 a5 a6 a7
             xs2 (Z_to_bv 64 ff) (Z_to_bv 64 S) xs5 (Z_to_bv 64 0) (wz P_A_SCHED_GET_DEFAULT_TASK) (Z_to_bv 64 ioc) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
        F (Z_to_bv 64 P_A_SC_U1) fc None m (seg_rom asegs)).
